using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut;

        public NotificationServiceTests()
        {
            _sut = new NotificationService();
            DrainQueue();
        }

        public void Dispose()
        {
            DrainQueue();
            _sut.Dispose();
        }

        private void DrainQueue()
        {
            while (_sut.ReceiveNotification() != null) { }
        }

        [Fact]
        public void SendNotification_WithDisplayName_MessageContainsDisplayName()
        {
            _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("New Student 'John Doe' has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_MessageContainsIdFallback()
        {
            _sut.SendNotification("Student", "42", null, EntityOperation.CREATE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("New Student (ID: 42) has been created", notification.Message);
        }

        [Theory]
        [InlineData(EntityOperation.CREATE, "New Student 'Alice' has been created")]
        [InlineData(EntityOperation.UPDATE, "Student 'Alice' has been updated")]
        [InlineData(EntityOperation.DELETE, "Student 'Alice' has been deleted")]
        public void SendNotification_OperationType_GeneratesCorrectMessage(EntityOperation operation, string expectedMessage)
        {
            _sut.SendNotification("Student", "1", "Alice", operation);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal(expectedMessage, notification.Message);
        }

        [Fact]
        public void SendNotification_NullUserName_CreatedByDefaultsToSystem()
        {
            _sut.SendNotification("Course", "5", "Math 101", EntityOperation.CREATE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_WithUserName_CreatedByIsSet()
        {
            _sut.SendNotification("Course", "5", "Math 101", EntityOperation.UPDATE, "admin@contoso.com");

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("admin@contoso.com", notification.CreatedBy);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            var result = _sut.ReceiveNotification();

            Assert.Null(result);
        }

        [Fact]
        public void SendThenReceive_ReturnsEnqueuedNotification()
        {
            _sut.SendNotification("Enrollment", "10", "CS101-Enrollment", EntityOperation.CREATE, "testuser");

