            Assert.NotNull(notification);
            Assert.Equal("Enrollment", notification.EntityType);
            Assert.Equal("10", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("New Enrollment 'CS101-Enrollment' has been created", notification.Message);
            Assert.Equal("testuser", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void MultipleSends_ReceivedInFIFOOrder()
        {
            _sut.SendNotification("Student", "1", "First", EntityOperation.CREATE);
            _sut.SendNotification("Student", "2", "Second", EntityOperation.UPDATE);
            _sut.SendNotification("Student", "3", "Third", EntityOperation.DELETE);

            var first = _sut.ReceiveNotification();
            var second = _sut.ReceiveNotification();
            var third = _sut.ReceiveNotification();

            Assert.Equal("New Student 'First' has been created", first!.Message);
            Assert.Equal("Student 'Second' has been updated", second!.Message);
            Assert.Equal("Student 'Third' has been deleted", third!.Message);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            var exception = Record.Exception(() => _sut.MarkAsRead(999));

            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var service = new NotificationService();

            var exception = Record.Exception(() => service.Dispose());

            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_TwoParameterOverload_Works()
        {
            _sut.SendNotification("Department", "7", EntityOperation.DELETE, "admin");

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Department (ID: 7) has been deleted", notification.Message);
            Assert.Equal("Department", notification.EntityType);
            Assert.Equal("7", notification.EntityId);
            Assert.Equal("DELETE", notification.Operation);
            Assert.Equal("admin", notification.CreatedBy);
        }

