        public void GenerateMessage_AllOperations_WithoutDisplayName_CorrectMessage(EntityOperation operation, string expectedMessage)
        {
            _sut.SendNotification("Course", "1", null, operation);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal(expectedMessage, notification.Message);
        }

