        [InlineData(EntityOperation.CREATE, "New Instructor 'Dr. Smith' has been created")]
        [InlineData(EntityOperation.UPDATE, "Instructor 'Dr. Smith' has been updated")]
        [InlineData(EntityOperation.DELETE, "Instructor 'Dr. Smith' has been deleted")]
        public void GenerateMessage_AllOperations_WithDisplayName_CorrectMessage(EntityOperation operation, string expectedMessage)
        {
            _sut.SendNotification("Instructor", "1", "Dr. Smith", operation);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal(expectedMessage, notification.Message);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToRecentTime()
        {
            var before = DateTime.Now.AddSeconds(-1);

            _sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE);

            var notification = _sut.ReceiveNotification();
            var after = DateTime.Now.AddSeconds(1);

            Assert.NotNull(notification);
            Assert.InRange(notification.CreatedAt, before, after);
        }

        [Fact]
        public void SendNotification_SetsIsReadToFalse()
        {
            _sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.False(notification.IsRead);
        }

        [Theory]
        [InlineData("")]
        [InlineData("   ")]
        public void SendNotification_EmptyOrWhitespaceDisplayName_FallsBackToIdFormat(string displayName)
        {
            _sut.SendNotification("Student", "99", displayName, EntityOperation.UPDATE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Student (ID: 99) has been updated", notification.Message);
        }
    }
}

