using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests : IDisposable
    {
        private SchoolContext _context;
        private InstructorsController _controller;

        private SchoolContext CreateContext(string dbName = null)
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName ?? Guid.NewGuid().ToString())
                .Options;
            return new SchoolContext(options);
        }

        private void SetupControllerWithContext(string dbName = null)
        {
            _context = CreateContext(dbName);
            _controller = new InstructorsController(_context);
        }

        private Instructor CreateInstructor(string firstName, string lastName, DateTime? hireDate = null)
        {
            return new Instructor
            {
                FirstMidName = firstName,
                LastName = lastName,
                HireDate = hireDate ?? DateTime.Parse("2020-01-01"),
                CourseAssignments = new List<CourseAssignment>()
            };
        }

        public void Dispose()
        {
            _controller?.Dispose();
            _context?.Dispose();
        }

        // --- Index Tests ---

        [Fact]
        public void Index_NoParams_ReturnsViewWithInstructorIndexData()
        {
            SetupControllerWithContext();
            var instructor = CreateInstructor("Test", "Instructor");
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var result = _controller.Index(null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.Single(model.Instructors);
        }

        [Fact]
        public void Index_WithInstructorId_SetsCourses()
        {
            SetupControllerWithContext();
            var dept = new Department { Name = "TestDept", Budget = 100, StartDate = DateTime.Parse("2020-01-01") };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course
            {
                CourseID = 1001,
                Title = "TestCourse",
                Credits = 3,
                DepartmentID = dept.DepartmentID,
                Enrollments = new List<Enrollment>()
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var instructor = CreateInstructor("Test", "Instructor");
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var ca = new CourseAssignment { InstructorID = instructor.ID, CourseID = course.CourseID };
            _context.CourseAssignments.Add(ca);
            _context.SaveChanges();

            var result = _controller.Index(instructor.ID, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.NotNull(model.Courses);
            Assert.Single(model.Courses);
        }

        [Fact]
        public void Index_ReturnsInstructorsOrderedByLastName()
        {
            SetupControllerWithContext();
            _context.Instructors.Add(CreateInstructor("Zoe", "Zeta"));
            _context.Instructors.Add(CreateInstructor("Alice", "Alpha"));
            _context.Instructors.Add(CreateInstructor("Mike", "Middle"));
            _context.SaveChanges();

            var result = _controller.Index(null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            var instructors = model.Instructors.ToList();
            Assert.Equal(3, instructors.Count);
            Assert.Equal("Alpha", instructors[0].LastName);
            Assert.Equal("Middle", instructors[1].LastName);
            Assert.Equal("Zeta", instructors[2].LastName);
        }

        // --- Details Tests ---

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            SetupControllerWithContext();

            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsView()
        {
            SetupControllerWithContext();
            var instructor = CreateInstructor("Test", "Instructor");
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var result = _controller.Details(instructor.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.Equal("Instructor", model.LastName);
        }

        [Fact]
        public void Details_InvalidId_ReturnsNotFound()
        {
            SetupControllerWithContext();

            var result = _controller.Details(999);

            Assert.IsType<NotFoundResult>(result);
        }

        // --- Create GET Tests ---

        [Fact]
        public void Create_Get_ReturnsViewWithNewInstructor()
        {
            SetupControllerWithContext();

            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.NotNull(model.CourseAssignments);
            Assert.Empty(model.CourseAssignments);
        }

        // --- Create POST Tests ---

        [Fact]
        public void Create_Post_ValidInstructor_RedirectsToIndex()
        {
            SetupControllerWithContext();
            var instructor = CreateInstructor("New", "Teacher");

            var result = _controller.Create(instructor, null) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Single(_context.Instructors);
        }

        [Fact]
        public void Create_Post_WithSelectedCourses_AddsCourseAssignments()
        {
            SetupControllerWithContext();
            var dept = new Department { Name = "Dept", Budget = 100, StartDate = DateTime.Parse("2020-01-01") };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course1 = new Course { CourseID = 2001, Title = "Course1", Credits = 3, DepartmentID = dept.DepartmentID };
            var course2 = new Course { CourseID = 2002, Title = "Course2", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.AddRange(course1, course2);
            _context.SaveChanges();

            var instructor = CreateInstructor("New", "Teacher");

            var result = _controller.Create(instructor, new[] { "2001", "2002" }) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            var saved = _context.Instructors.Include(i => i.CourseAssignments).Single();
            Assert.Equal(2, saved.CourseAssignments.Count);
        }

        // --- Delete GET Tests ---

        [Fact]
        public void Delete_NullId_ReturnsBadRequest()
        {
            SetupControllerWithContext();

            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_ValidId_ReturnsView()
        {
            SetupControllerWithContext();
            var instructor = CreateInstructor("Test", "Instructor");
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var result = _controller.Delete(instructor.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.Equal("Instructor", model.LastName);
        }

        [Fact]
        public void Delete_InvalidId_ReturnsNotFound()
        {
            SetupControllerWithContext();

            var result = _controller.Delete(999);

            Assert.IsType<NotFoundResult>(result);
        }

        // --- DeleteConfirmed Tests ---

        [Fact]
        public void DeleteConfirmed_RemovesInstructor()
        {
            SetupControllerWithContext();
            var instructor = CreateInstructor("Test", "Instructor");
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var result = _controller.DeleteConfirmed(instructor.ID) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Empty(_context.Instructors);
        }

        [Fact]
        public void DeleteConfirmed_ClearsDepartmentAdministrator()
        {
            SetupControllerWithContext();
            var instructor = CreateInstructor("Test", "Instructor");
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var dept = new Department
            {
                Name = "TestDept",
                Budget = 1000,
                StartDate = DateTime.Parse("2020-01-01"),
                InstructorID = instructor.ID
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            _controller.DeleteConfirmed(instructor.ID);

            var updatedDept = _context.Departments.Single();
            Assert.Null(updatedDept.InstructorID);
        }
    }
}

