using System;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;

        public CoursesControllerTests()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: Guid.NewGuid().ToString())
                .Options;
            _context = new SchoolContext(options);

            var mockEnv = new Mock<IWebHostEnvironment>();
            mockEnv.Setup(e => e.ContentRootPath).Returns("/fake/test");
            mockEnv.Setup(e => e.WebRootPath).Returns("/fake/test/wwwroot");
            var mockLogger = new Mock<ILogger<CoursesController>>();

            _controller = new CoursesController(_context, mockEnv.Object, mockLogger.Object);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Department SeedDepartment()
        {
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 100000m,
                StartDate = DateTime.Parse("2020-01-01")
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        private Course SeedCourse(int departmentId = 1)
        {
            var course = new Course
            {
                CourseID = 1001,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = departmentId
            };
            _context.Courses.Add(course);
            _context.SaveChanges();
            return course;
        }

        [Fact]
        public void Index_ReturnsViewWithAllCourses()
        {
            SeedDepartment();
            SeedCourse();

            var result = _controller.Index();

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<System.Collections.Generic.List<Course>>(viewResult.Model);
            Assert.Single(model);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithCourse()
        {
            SeedDepartment();
            SeedCourse();

            var result = _controller.Details(1001);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Course>(viewResult.Model);
            Assert.Equal("Chemistry", model.Title);
        }

        [Fact]
        public void Create_Get_ReturnsViewWithNewCourse()
        {
            SeedDepartment();

            var result = _controller.Create();

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.IsType<Course>(viewResult.Model);
        }

        [Fact]
        public void Create_Post_ValidCourse_NoImage_RedirectsToIndex()
        {
            SeedDepartment();
            var course = new Course
            {
                CourseID = 2002,
                Title = "Physics",
                Credits = 4,
                DepartmentID = 1
            };

            var result = _controller.Create(course, null);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Equal(1, _context.Courses.Count());
        }

        [Fact]
        public void Create_Post_InvalidModel_ReturnsView()
        {
            SeedDepartment();
            _controller.ModelState.AddModelError("Title", "Required");
            var course = new Course { CourseID = 3003, DepartmentID = 1 };

            var result = _controller.Create(course, null);

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void Edit_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_ValidId_ReturnsView()
        {
            SeedDepartment();
            SeedCourse();

            var result = _controller.Edit(1001);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Course>(viewResult.Model);
            Assert.Equal("Chemistry", model.Title);
        }

        [Fact]
        public void Edit_InvalidId_ReturnsNotFound()
        {
            var result = _controller.Edit(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Post_ValidCourse_RedirectsToIndex()
        {
            SeedDepartment();
            SeedCourse();
            // Detach the tracked entity so we can attach the edited one
            var tracked = _context.Courses.Find(1001);
            _context.Entry(tracked).State = EntityState.Detached;

            var editedCourse = new Course
            {
                CourseID = 1001,
                Title = "Advanced Chemistry",
                Credits = 4,
                DepartmentID = 1
            };

            var result = _controller.Edit(editedCourse, null);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Delete_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_ValidId_ReturnsView()
        {
            SeedDepartment();
            SeedCourse();

            var result = _controller.Delete(1001);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Course>(viewResult.Model);
            Assert.Equal("Chemistry", model.Title);
        }

        [Fact]
        public void DeleteConfirmed_RemovesAndRedirects()
        {
            SeedDepartment();
            SeedCourse();

            var result = _controller.DeleteConfirmed(1001);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Equal(0, _context.Courses.Count());
        }
    }
}

