using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;
using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Models
{
    public class PersonTests
    {
        private static List<ValidationResult> ValidateModel(object model)
        {
            var results = new List<ValidationResult>();
            var context = new ValidationContext(model);
            Validator.TryValidateObject(model, context, results, validateAllProperties: true);
            return results;
        }

        [Fact]
        public void FullName_ReturnsLastNameCommaFirstMidName()
        {
            var student = new Student
            {
                LastName = "Smith",
                FirstMidName = "John",
                EnrollmentDate = System.DateTime.Now
            };

            Assert.Equal("Smith, John", student.FullName);
        }

        [Theory]
        [InlineData("Doe", "Jane", "Doe, Jane")]
        [InlineData("O'Brien", "Conan", "O'Brien, Conan")]
        [InlineData("X", "Y", "X, Y")]
        public void FullName_VariousNames_ReturnsCorrectFormat(string lastName, string firstName, string expected)
        {
            var student = new Student
            {
                LastName = lastName,
                FirstMidName = firstName,
                EnrollmentDate = System.DateTime.Now
            };

            Assert.Equal(expected, student.FullName);
        }

        [Fact]
        public void Validation_MissingLastName_Fails()
        {
            var student = new Student
            {
                FirstMidName = "John",
                EnrollmentDate = System.DateTime.Now
            };

            var results = ValidateModel(student);

            Assert.Contains(results, r => r.MemberNames.Contains("LastName"));
        }

        [Fact]
        public void Validation_MissingFirstMidName_Fails()
        {
            var student = new Student
            {
                LastName = "Smith",
                EnrollmentDate = System.DateTime.Now
            };

            var results = ValidateModel(student);

            Assert.Contains(results, r => r.MemberNames.Contains("FirstMidName"));
        }

        [Fact]
        public void Validation_LastNameExceeds50Characters_Fails()
        {
            var student = new Student
            {
                LastName = new string('A', 51),
                FirstMidName = "John",
                EnrollmentDate = System.DateTime.Now
            };

            var results = ValidateModel(student);

            Assert.Contains(results, r => r.MemberNames.Contains("LastName"));
        }

        [Fact]
        public void Validation_FirstMidNameExceeds50Characters_Fails()
        {
            var student = new Student
            {
                LastName = "Smith",
                FirstMidName = new string('A', 51),
                EnrollmentDate = System.DateTime.Now
            };

            var results = ValidateModel(student);

            Assert.Contains(results, r => r.MemberNames.Contains("FirstMidName"));
        }

        [Fact]
        public void Validation_FirstMidNameExceeds50Characters_HasCorrectErrorMessage()
        {
            var student = new Student
            {
                LastName = "Smith",
                FirstMidName = new string('A', 51),
                EnrollmentDate = System.DateTime.Now
            };

            var results = ValidateModel(student);

            Assert.Contains(results, r =>
                r.ErrorMessage != null &&
                r.ErrorMessage.Contains("First name cannot be longer than 50 characters."));
        }

        [Fact]
        public void Validation_ValidPerson_Passes()
        {
            var student = new Student
            {
                LastName = "Smith",
                FirstMidName = "John",
                EnrollmentDate = System.DateTime.Now
            };

            var results = ValidateModel(student);

            Assert.DoesNotContain(results, r =>
                r.MemberNames.Contains("LastName") || r.MemberNames.Contains("FirstMidName"));
        }

        [Fact]
        public void Validation_LastNameExactly50Characters_Passes()
        {
            var student = new Student
            {
                LastName = new string('A', 50),
                FirstMidName = "John",
                EnrollmentDate = System.DateTime.Now
            };

            var results = ValidateModel(student);

            Assert.DoesNotContain(results, r => r.MemberNames.Contains("LastName"));
        }
    }
}

