using System;
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;
using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Models
{
    public class NotificationTests
    {
        private static List<ValidationResult> ValidateModel(object model)
        {
            var results = new List<ValidationResult>();
            var context = new ValidationContext(model);
            Validator.TryValidateObject(model, context, results, validateAllProperties: true);
            return results;
        }

        [Fact]
        public void Properties_CanBeSetAndRead()
        {
            var now = DateTime.UtcNow;
            var readAt = now.AddMinutes(5);

            var notification = new Notification
            {
                Id = 1,
                EntityType = "Student",
                EntityId = "42",
                Operation = "CREATE",
                Message = "Student created",
                CreatedAt = now,
                CreatedBy = "admin",
                IsRead = true,
                ReadAt = readAt
            };

            Assert.Equal(1, notification.Id);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("Student created", notification.Message);
            Assert.Equal(now, notification.CreatedAt);
            Assert.Equal("admin", notification.CreatedBy);
            Assert.True(notification.IsRead);
            Assert.Equal(readAt, notification.ReadAt);
        }

        [Fact]
        public void ReadAt_DefaultsToNull()
        {
            var notification = new Notification();

            Assert.Null(notification.ReadAt);
        }

        [Fact]
        public void IsRead_DefaultsToFalse()
        {
            var notification = new Notification();

            Assert.False(notification.IsRead);
        }

        [Fact]
        public void Validation_ValidNotification_Passes()
        {
            var notification = new Notification
            {
                EntityType = "Course",
                EntityId = "101",
                Operation = "UPDATE",
                Message = "Course updated",
                CreatedAt = DateTime.UtcNow
            };

            var results = ValidateModel(notification);

            Assert.Empty(results);
        }

        [Fact]
        public void Validation_MissingRequiredFields_Fails()
        {
            var notification = new Notification();

            var results = ValidateModel(notification);

            Assert.Contains(results, r => r.MemberNames.Contains("EntityType"));
            Assert.Contains(results, r => r.MemberNames.Contains("EntityId"));
            Assert.Contains(results, r => r.MemberNames.Contains("Operation"));
            Assert.Contains(results, r => r.MemberNames.Contains("Message"));
        }

        [Fact]
        public void Validation_EntityTypeExceedsMaxLength_Fails()
        {
            var notification = new Notification
            {
                EntityType = new string('A', 101),
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test",
                CreatedAt = DateTime.UtcNow
            };

            var results = ValidateModel(notification);

            Assert.Contains(results, r => r.MemberNames.Contains("EntityType"));
        }

        [Fact]
        public void EntityOperation_HasExpectedValues()
        {
            Assert.Equal(0, (int)EntityOperation.CREATE);
            Assert.Equal(1, (int)EntityOperation.UPDATE);
            Assert.Equal(2, (int)EntityOperation.DELETE);
        }

        [Fact]
        public void EntityOperation_HasThreeValues()
        {
            var values = Enum.GetValues(typeof(EntityOperation));

            Assert.Equal(3, values.Length);
        }

        [Theory]
        [InlineData("CREATE")]
        [InlineData("UPDATE")]
        [InlineData("DELETE")]
        public void EntityOperation_CanBeParsedFromString(string operationName)
        {
            var parsed = Enum.Parse<EntityOperation>(operationName);

            Assert.True(Enum.IsDefined(typeof(EntityOperation), parsed));
        }
    }
}

