+    public class PaginatedListTests
+    {
+        [Fact]
+        public void Constructor_SetsPageIndex()
+        {
+            var list = new PaginatedList<int>(new List<int> { 1, 2 }, 10, 2, 5);
+
+            Assert.Equal(2, list.PageIndex);
+        }
+
+        [Fact]
+        public void Constructor_SetsTotalPages()
+        {
+            var list = new PaginatedList<int>(new List<int> { 1, 2 }, 10, 1, 5);
+
+            Assert.Equal(2, list.TotalPages);
+        }
+
+        [Fact]
+        public void Constructor_AddsItemsToList()
+        {
+            var items = new List<int> { 1, 2, 3 };
+
+            var list = new PaginatedList<int>(items, 10, 1, 5);
+
+            Assert.Equal(3, list.Count);
+            Assert.Contains(1, list);
+            Assert.Contains(2, list);
+            Assert.Contains(3, list);
+        }
+
+        [Fact]
+        public void TotalPages_Count11PageSize5_Returns3()
+        {
+            var list = new PaginatedList<int>(new List<int>(), 11, 1, 5);
+
+            Assert.Equal(3, list.TotalPages);
+        }
+
+        [Fact]
+        public void TotalPages_Count10PageSize5_Returns2()
+        {
