using System;
using System.Linq;
using ContosoUniversity;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private SchoolContext _context;
        private StudentsController _controller;

        private SchoolContext CreateContext(string dbName = null)
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName ?? Guid.NewGuid().ToString())
                .Options;
            return new SchoolContext(options);
        }

        private StudentsController CreateController(SchoolContext context)
        {
            var controller = new StudentsController(context);
            controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
            return controller;
        }

        private void SeedStudents(SchoolContext context, params Student[] students)
        {
            context.Students.AddRange(students);
            context.SaveChanges();
        }

        private Student MakeStudent(string last, string first, DateTime date)
        {
            return new Student
            {
                LastName = last,
                FirstMidName = first,
                EnrollmentDate = date
            };
        }

        public void Dispose()
        {
            _controller?.Dispose();
            _context?.Dispose();
        }

        // ── Index ──────────────────────────────────────────────

        [Fact]
        public void Index_NoParams_ReturnsViewWithAllStudents()
        {
            _context = CreateContext();
            SeedStudents(_context,
                MakeStudent("Adams", "John", new DateTime(2023, 1, 1)),
                MakeStudent("Baker", "Jane", new DateTime(2023, 2, 1)),
                MakeStudent("Clark", "Bob", new DateTime(2023, 3, 1)));
            _controller = CreateController(_context);

            var result = _controller.Index(null, null, null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(3, model.Count);
        }

        [Fact]
        public void Index_SearchByLastName_FiltersCorrectly()
        {
            _context = CreateContext();
            SeedStudents(_context,
                MakeStudent("Adams", "John", new DateTime(2023, 1, 1)),
                MakeStudent("Baker", "Jane", new DateTime(2023, 2, 1)));
            _controller = CreateController(_context);

            var result = _controller.Index(null, null, "Adams", null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Single(model);
            Assert.Equal("Adams", model[0].LastName);
        }

        [Fact]
        public void Index_SearchByFirstName_FiltersCorrectly()
        {
            _context = CreateContext();
            SeedStudents(_context,
                MakeStudent("Adams", "John", new DateTime(2023, 1, 1)),
                MakeStudent("Baker", "Jane", new DateTime(2023, 2, 1)));
            _controller = CreateController(_context);

            var result = _controller.Index(null, null, "Jane", null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Single(model);
            Assert.Equal("Jane", model[0].FirstMidName);
        }

        [Fact]
        public void Index_SortByNameDesc_ReturnsDescendingOrder()
        {
            _context = CreateContext();
            SeedStudents(_context,
                MakeStudent("Adams", "A", new DateTime(2023, 1, 1)),
                MakeStudent("Clark", "C", new DateTime(2023, 2, 1)),
                MakeStudent("Baker", "B", new DateTime(2023, 3, 1)));
            _controller = CreateController(_context);

            var result = _controller.Index("name_desc", null, null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Equal("Clark", model[0].LastName);
            Assert.Equal("Baker", model[1].LastName);
            Assert.Equal("Adams", model[2].LastName);
        }

        [Fact]
        public void Index_SortByDate_ReturnsSortedByDate()
        {
            _context = CreateContext();
            SeedStudents(_context,
                MakeStudent("Adams", "A", new DateTime(2023, 3, 1)),
                MakeStudent("Baker", "B", new DateTime(2023, 1, 1)),
                MakeStudent("Clark", "C", new DateTime(2023, 2, 1)));
            _controller = CreateController(_context);

            var result = _controller.Index("Date", null, null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Equal("Baker", model[0].LastName);
            Assert.Equal("Clark", model[1].LastName);
            Assert.Equal("Adams", model[2].LastName);
        }

        [Fact]
        public void Index_SortByDateDesc_ReturnsSortedByDateDesc()
        {
            _context = CreateContext();
            SeedStudents(_context,
                MakeStudent("Adams", "A", new DateTime(2023, 3, 1)),
                MakeStudent("Baker", "B", new DateTime(2023, 1, 1)),
                MakeStudent("Clark", "C", new DateTime(2023, 2, 1)));
            _controller = CreateController(_context);

            var result = _controller.Index("date_desc", null, null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Equal("Adams", model[0].LastName);
            Assert.Equal("Clark", model[1].LastName);
            Assert.Equal("Baker", model[2].LastName);
        }

        [Fact]
        public void Index_DefaultSort_ReturnsSortedByLastNameAsc()
        {
            _context = CreateContext();
            SeedStudents(_context,
                MakeStudent("Clark", "C", new DateTime(2023, 1, 1)),
                MakeStudent("Adams", "A", new DateTime(2023, 2, 1)),
                MakeStudent("Baker", "B", new DateTime(2023, 3, 1)));
            _controller = CreateController(_context);

            var result = _controller.Index(null, null, null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Equal("Adams", model[0].LastName);
            Assert.Equal("Baker", model[1].LastName);
            Assert.Equal("Clark", model[2].LastName);
        }

        [Fact]
        public void Index_NewSearchString_ResetsPageTo1()
        {
            _context = CreateContext();
            SeedStudents(_context, MakeStudent("Adams", "A", new DateTime(2023, 1, 1)));
            _controller = CreateController(_context);

            // When searchString is non-null, page should be reset to 1
            var result = _controller.Index(null, null, "Adams", 5) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Equal(1, model.PageIndex);
        }

        [Fact]
        public void Index_NullSearchString_UsesCurrentFilter()
        {
            _context = CreateContext();
            SeedStudents(_context,
                MakeStudent("Adams", "A", new DateTime(2023, 1, 1)),
                MakeStudent("Baker", "B", new DateTime(2023, 2, 1)));
            _controller = CreateController(_context);

            // searchString is null → uses currentFilter
            var result = _controller.Index(null, "Adams", null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Single(model);
            Assert.Equal("Adams", model[0].LastName);
        }

        [Fact]
        public void Index_SetsSortViewBagProperties()
        {
            _context = CreateContext();
            _controller = CreateController(_context);

            _controller.Index(null, null, null, null);

            Assert.Null(_controller.ViewBag.CurrentSort);
            Assert.Equal("name_desc", (string)_controller.ViewBag.NameSortParm);
            Assert.Equal("Date", (string)_controller.ViewBag.DateSortParm);
        }

        // ── Details ────────────────────────────────────────────

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            _context = CreateContext();
            _controller = CreateController(_context);

            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithStudent()
        {
            _context = CreateContext();
            var student = MakeStudent("Adams", "John", new DateTime(2023, 1, 1));
            SeedStudents(_context, student);
            _controller = CreateController(_context);

