using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class HomeControllerTests
    {
        private SchoolContext CreateContext()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(Guid.NewGuid().ToString())
                .Options;
            return new SchoolContext(options);
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            // Arrange
            using var context = CreateContext();
            var controller = new HomeController(context);

            // Act
            var result = controller.Index();

            // Assert
            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void About_ReturnsViewResult_WithEnrollmentDateGroupList()
        {
            // Arrange
            using var context = CreateContext();
            var controller = new HomeController(context);

            // Act
            var result = controller.About();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.IsType<List<EnrollmentDateGroup>>(viewResult.Model);
        }

        [Fact]
        public void About_WithStudents_GroupsByEnrollmentDateWithCorrectCounts()
        {
            // Arrange
            using var context = CreateContext();
            var date1 = new DateTime(2020, 9, 1);
            var date2 = new DateTime(2021, 9, 1);

            context.Students.AddRange(
                new Student { LastName = "A", FirstMidName = "A1", EnrollmentDate = date1 },
                new Student { LastName = "B", FirstMidName = "B1", EnrollmentDate = date1 },
                new Student { LastName = "C", FirstMidName = "C1", EnrollmentDate = date2 }
            );
            context.SaveChanges();

            var controller = new HomeController(context);

            // Act
            var result = controller.About();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<List<EnrollmentDateGroup>>(viewResult.Model);
            Assert.Equal(2, model.Count);

            var group1 = model.Single(g => g.EnrollmentDate == date1);
            Assert.Equal(2, group1.StudentCount);

            var group2 = model.Single(g => g.EnrollmentDate == date2);
            Assert.Equal(1, group2.StudentCount);
        }

        [Fact]
        public void About_WithNoStudents_ReturnsEmptyList()
        {
            // Arrange
            using var context = CreateContext();
            var controller = new HomeController(context);

            // Act
            var result = controller.About();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<List<EnrollmentDateGroup>>(viewResult.Model);
            Assert.Empty(model);
        }

        [Fact]
        public void Contact_ReturnsViewResult_WithViewBagMessage()
        {
            // Arrange
            using var context = CreateContext();
            var controller = new HomeController(context);

            // Act
            var result = controller.Contact();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.Equal("Your contact page.", controller.ViewBag.Message);
        }

