        {
            // Arrange
            using var context = CreateContext();
            var controller = new HomeController(context);

            // Act
            var result = controller.Unauthorized();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.Equal("You don't have permission to access this resource.", controller.ViewBag.Message);
        }
    }
}

using System;
using System.Text.Json;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly NotificationService _drainService = new NotificationService();

        public NotificationsControllerTests()
        {
            // Drain the static queue before each test
            while (_drainService.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            // Drain after each test to avoid leaking state
            while (_drainService.ReceiveNotification() != null) { }
            _drainService.Dispose();
        }

        private SchoolContext CreateContext()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(Guid.NewGuid().ToString())
                .Options;
            return new SchoolContext(options);
        }

        [Fact]
        public void GetNotifications_NoNotifications_ReturnsSuccessTrueAndCountZero()
        {
            // Arrange
            using var context = CreateContext();
            var controller = new NotificationsController(context);

            // Act
            var result = controller.GetNotifications();

            // Assert
            Assert.IsType<JsonResult>(result);
            var json = JsonSerializer.Serialize(result.Value);
            var doc = JsonDocument.Parse(json);
            Assert.True(doc.RootElement.GetProperty("success").GetBoolean());
            Assert.Equal(0, doc.RootElement.GetProperty("count").GetInt32());
        }

        [Fact]
        public void GetNotifications_AfterSendingNotifications_ReturnsThem()
        {
            // Arrange
            using var context = CreateContext();
            var service = new NotificationService();
            service.SendNotification("Student", "1", "John", EntityOperation.CREATE, "Admin");
            service.SendNotification("Course", "2", "Math", EntityOperation.UPDATE, "Admin");

            var controller = new NotificationsController(context);

            // Act
            var result = controller.GetNotifications();

            // Assert
            var json = JsonSerializer.Serialize(result.Value);
            var doc = JsonDocument.Parse(json);
            Assert.True(doc.RootElement.GetProperty("success").GetBoolean());
            Assert.Equal(2, doc.RootElement.GetProperty("count").GetInt32());

            var notifications = doc.RootElement.GetProperty("notifications");
            Assert.Equal(2, notifications.GetArrayLength());
        }

        [Fact]
        public void GetNotifications_LimitsToTenNotifications()
        {
            // Arrange
            using var context = CreateContext();
            var service = new NotificationService();
            for (int i = 0; i < 15; i++)
            {
                service.SendNotification("Student", i.ToString(), $"Student{i}", EntityOperation.CREATE, "Admin");
            }

            var controller = new NotificationsController(context);

            // Act
            var result = controller.GetNotifications();

            // Assert
            var json = JsonSerializer.Serialize(result.Value);
            var doc = JsonDocument.Parse(json);
            Assert.True(doc.RootElement.GetProperty("success").GetBoolean());
            Assert.Equal(10, doc.RootElement.GetProperty("count").GetInt32());

            var notifications = doc.RootElement.GetProperty("notifications");
            Assert.Equal(10, notifications.GetArrayLength());
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccessTrue()
        {
            // Arrange
            using var context = CreateContext();
            var controller = new NotificationsController(context);

            // Act
            var result = controller.MarkAsRead(1);

            // Assert
            Assert.IsType<JsonResult>(result);
            var json = JsonSerializer.Serialize(result.Value);
            var doc = JsonDocument.Parse(json);
            Assert.True(doc.RootElement.GetProperty("success").GetBoolean());
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            // Arrange
            using var context = CreateContext();
            var controller = new NotificationsController(context);

            // Act
            var result = controller.Index();

            // Assert
            Assert.IsType<ViewResult>(result);
        }
    }
}

